// App.js
import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [resumes, setResumes] = useState([]);
  const [jobDescription, setJobDescription] = useState('');
  const [loading, setLoading] = useState(false);

  const uploadResume = async (file) => {
    const formData = new FormData();
    formData.append('file', file);

    const response = await axios.post('/upload-resume/', formData);
    return response.data;
  };

  const matchResume = async (resumeId, jobId) => {
    const response = await axios.post('/match-resume/', {
      resume_id: resumeId,
      job_id: jobId
    });
    return response.data;
  };

  const getShortlisted = async () => {
    const response = await axios.get('/shortlisted/?min_score=7');
    setResumes(response.data);
  };

  // UI Components
  const CandidateCard = ({ resume }) => (
    <div className="candidate-card">
      <h3>{resume.name || 'Candidate'}</h3>
      <div className="match-score">
        Match Score: {resume.match_score}/10
      </div>
      <div className="justification">
        {resume.justification}
      </div>
      <div className="skills">
        <strong>Skills:</strong> {resume.skills.join(', ')}
      </div>
      <div className="experience">
        <strong>Experience:</strong> {resume.experience}
      </div>
    </div>
  );

  return (
    <div className="App">
      <header>
        <h1>Smart Resume Screener</h1>
      </header>

      <section className="upload-section">
        <div className="job-input">
          <textarea
            placeholder="Paste Job Description"
            value={jobDescription}
            onChange={(e) => setJobDescription(e.target.value)}
          />
          <button>Save Job</button>
        </div>

        <div className="resume-upload">
          <input
            type="file"
            accept=".pdf,.docx"
            onChange={(e) => uploadResume(e.target.files[0])}
          />
        </div>
      </section>

      <section className="shortlisted-section">
        <h2>Shortlisted Candidates</h2>
        <button onClick={getShortlisted}>Refresh List</button>
        <div className="candidates-list">
          {resumes.map((resume, index) => (
            <CandidateCard key={index} resume={resume} />
          ))}
        </div>
      </section>
    </div>
  );
}

export default App;
